                left, right = (a,b) if a['left'] < b['left'] else (b,a)
                directions[id(left)] = -1
                directions[id(right)] = 1
        else:
            o = group[0]
            mid = (o['top'] + o['bottom']) / 2
            # Single objects travel toward the nearer vertical edge.
            directions[id(o)] = -1 if mid < (h-1)/2 else 1
    out = [[0]*w for _ in range(h)]
    for o in objects:
        cells = o['cells']; top, bottom = o['top'], o['bottom']
        if directions[id(o)] < 0: shift = -top
        else: shift = h-1-bottom
        for y,x in cells: out[y+shift][x] = o['color']
    return out

