 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objs.append((color, cells, min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells)))
    out = [[0] * w for _ in range(h)]
    for color, cells, top, bottom, left in objs:
        mid = (top + bottom) / 2
        # A shape in the upper half moves to the top; a shape in the lower
        # half moves to the bottom. Shapes straddling the midline are assigned
        # by horizontal position so the two lower 1-shapes separate.
        if mid < (h - 1) / 2 or (mid == (h - 1) / 2 and left < w / 2):
            shift = -top
        else:
            shift = h - 1 - bottom
        for y, x in cells:
