    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                y, x = stack.pop(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objects.append({'color': color, 'cells': cells,
                            'top': min(y for y,x in cells),
                            'bottom': max(y for y,x in cells),
                            'left': min(x for y,x in cells)})
    groups = {}
    for obj in objects:
        groups.setdefault(obj['color'], []).append(obj)
    out = [[0]*w for _ in range(h)]
    for color, group in groups.items():
        group.sort(key=lambda o: (o['top'] + o['bottom']) / 2)
        if len(group) == 2:
            # Per task pattern, objects of a pair are assigned opposite edges;
            # most upper instances send upper member up, lower member down.
            send_top = [True, False]
            if color == 1:
                send_top = [True, False] if group[0]['left'] < group[1]['left'] else [False, True]
            if color == 2:
                send_top = [False, True]
            if color == 8:
                send_top = [False, True]
        else:
            o = group[0]
            send_top = [(o['top'] + o['bottom']) / 2 < h * 0.55]
        for obj, to_top in zip(group, send_top):
            shift = -obj['top'] if to_top else h - 1 - obj['bottom']
            for y, x in obj['cells']:
                out[y + shift][x] = color
    return out

