 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # These grids contain independent solid outline motifs; each motif is a
    # separate 4-connected component. Their paired counterparts move to the
    # same edge-side output band indicated by the demo layout.
    seen, objs = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objs.append({'color':color,'cells':cells,'top':min(y for y,x in cells),
                         'bottom':max(y for y,x in cells),'left':min(x for y,x in cells)})
    out=[[0]*w for _ in range(h)]
    for obj in objs:
        # The demo rule: upper cluster set translates upward; bottom clusters
        # translate downward. Mid-grid motifs are assigned according to their
        # location in the formation (left half upper, right half lower).
        mid=(obj['top']+obj['bottom'])/2
        if mid < h/2 or (mid == h/2 and obj['left'] < w/2):
            shift=-obj['top']
        else:
            shift=h-1-obj['bottom']
        for y,x in obj['cells']:
            out[y+shift][x]=obj['color']
    return out

