    # Components in the upper part rise, and components in the lower part fall;
    # shapes near the center are allocated by their horizontal side.
    for o in comps:
        mid = (o['top'] + o['bottom']) / 2
        if mid < h/2 or (mid == h/2 and o['left'] < w/2):
            shift = -o['top']
        else:
            shift = h - 1 - o['bottom']
        for y, x in o['cells']:
            out[y+shift][x] = o['color']
    return out

