    # bottom-left and bottom-right motifs descend, except edge positions are
    # already occupied so each object's intended destination is its nearest
    # aligned output row.
    out = [[0]*w for _ in range(h)]
    for o in objs:
        if o['top'] < h/2:
            shift = -o['top']
        else:
            shift = h-1-o['bottom']
        for y,x in o['cells']:
